draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // book
  ctx.fillStyle = 'brown';
  ctx.fillRect(W/2-50, H/2-50, 100, 100);
  ctx.strokeRect(W/2-50, H/2-50, 100, 100);

  // stick figure
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2, H/2+70, 20, 0, 2 * Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2+90);
  ctx.lineTo(W/2, H/2+150);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2+120);
  ctx.lineTo(W/2-30, H/2+150);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2+120);
  ctx.lineTo(W/2+30, H/2+150);
  ctx.stroke();

  // reading animation
  ctx.beginPath();
  ctx.moveTo(W/2-40, H/2-30);
  ctx.lineTo(W/2-40+50*Math.sin(t), H/2-30);
  ctx.stroke();

  ctx.restore();
}
